ROW.COLUMN:
-- Only one part of UNION ALL will be executed -- threshold @Primary_Cust_Fl define which of them -- @Primary_Cust_Fl is parameter that indicates what account are included for customer focus to monitor : -- Y - cover only accounts for which a customer plays a primary role -- N - cover account over which a customer has a discretion -- PR-39791 -- Replaced (BUS_DAY_AGE = 0 and bus_day_fl='Y' ) with Clndr_Day_Age = 0 -- Replaced the Frequency Period calculation (max(t.data_dump_dt) > (select add_days(b.CLNDR_DT, - @Frequency_Period) from KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.BUS_DAY_AGE = 0 and b.bus_day_fl='Y' )) -- with (max(t.data_dump_dt) > (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL'and b.Clndr_Day_Age = @Frequency_Period )) -- Included "Exclude Cash Transaction Report Exemption Accounts" filter using coalesce (a.CASH_RPT_EXMPT_FL, ' ')<>'Y' -- Date: 3rd Feb 2010 : PR 42362 : Exclude cancelled and canceling transactions -- Added filter: tr.CXL_PAIR_TRXN_INTRL_ID is null --OFSAABD-17665 select v.Cust_Seq_Id , v.CUST_INTRL_ID as Cust_Intrl_Id , v.Effctv_Risk_Lvl , v.Actvty_Risk_Lvl , v.Lrf_Prctg , v.HR_Prctg , v.Trans_Amt , v.Trans_Ct , v.Acct_Ct , v.Overall_Risk , v.FUNC_CRNCY_CD from ( select t.CUST_INTRL_ID , max(t.CUST_SEQ_ID) as Cust_Seq_Id , max(t.CUST_EFCTV_RISK_NB) as Effctv_Risk_Lvl , max(t.d_ACTVTY_RISK_LVL) as Actvty_Risk_Lvl , case sum(t.Trxn_Am) when 0 then 0 else sum(t.d_LRF_TRXN_AM)*100 / sum(t.Trxn_Am) end as Lrf_Prctg , case sum(t.Trxn_Am) when 0 then 0 else sum(t.d_HR_TRXN_AM)*100 / sum(t.Trxn_Am) end as HR_Prctg , sum(t.Trxn_Am) as Trans_Amt , count(1) as Trans_Ct , count(distinct t.acct_intrl_id) as Acct_Ct , case when max(t.CUST_EFCTV_RISK_NB)>= @Effctv_Risk_Cutoff_Lvl and max(t.d_ACTVTY_RISK_LVL) >= @Actvty_Risk_Cutoff_Lvl then 'HR' when max(t.CUST_EFCTV_RISK_NB)< @Effctv_Risk_Cutoff_Lvl and max(t.d_ACTVTY_RISK_LVL) < @Actvty_Risk_Cutoff_Lvl then 'RR' else 'MR' end Overall_Risk , max(t.FUNC_CRNCY_CD) as FUNC_CRNCY_CD from (select c.CUST_INTRL_ID , DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) as Trxn_Am , c.CUST_SEQ_ID , ct1.CASH_TRXN_ACTVY_RISK_NB d_ACTVTY_RISK_LVL , ct1.DATA_DUMP_DT , a.ACCT_INTRL_ID , CASE WHEN DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM)-TRUNC(DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM),-@Lrf_Digits)=0 THEN DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) WHEN ct1.TRXN_ACTVY_AM-TRUNC(ct1.TRXN_ACTVY_AM,-@Lrf_Digits)=0 THEN DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) ELSE 0 END as d_LRF_TRXN_AM , c.CUST_EFCTV_RISK_NB , CASE WHEN ct1.CASH_TRXN_NTITY_RISK_NB>0 or ct1.CASH_TRXN_ACTVY_RISK_NB>0 THEN DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) ELSE 0 END d_HR_TRXN_AM , ct1.FUNC_CRNCY_CD from @MINER@.CASH_TRXN ct1 inner join @MINER@.ACCT a on a.ACCT_INTRL_ID = ct1.ACCT_INTRL_ID inner join @MINER@.CUST c on c.CUST_INTRL_ID=a.PRMRY_CUST_INTRL_ID WHERE -- Exclude cancelled and canceling transactions -- PR 42362 ct1.CXL_PAIR_TRXN_INTRL_ID is null --Exclude Exempted Customers and c.CUST_EFCTV_RISK_NB <> -2 -- Cover customers either from all jurisdiction or from Incl_Jurisdictions_Lst only and (@All_Jurisdictions_Fl='Y' or c.JRSDCN_CD in (@Incl_Jurisdictions_Lst)) -- Include Retail Customer Accounts Only and a.MANTAS_ACCT_HOLDR_TYPE_CD='CR' -- Cover only specific accounts and a.MANTAS_ACCT_BUS_TYPE_CD in (@Mantas_Bus_Acct_Type_Lst) -- and ct1.MANTAS_TRXN_PRDCT_CD in (@Incl_Cash_Trxn_Prdct_Type_Lst) and ct1.MANTAS_TRXN_PURP_CD = 'GENERAL' -- Cover either all transaction or only form the Incl_Trans_Src_Lst and (@All_Trans_Src_Fl='Y' or ct1.SRC_SYS_CD in (@Incl_Trans_Src_Lst)) -- PR-39791 start -- Exclude Cash Transaction Report Exemption Accounts and coalesce (a.CASH_RPT_EXMPT_FL, ' ')<>'Y' and ct1.TRXN_EXCTN_DT <= (select k0.clndr_dt from @MANTAS@.KDD_CAL k0 where k0.Clndr_Day_Age = 0 and k0.clndr_nm = 'SYSCAL') and ct1.TRXN_EXCTN_DT > (select k1.clndr_dt from @MANTAS@.KDD_CAL k1 where k1.Clndr_Day_Age = @Look_Back_Period and k1.clndr_nm = 'SYSCAL') and ct1.DATA_DUMP_DT <= (select k0.clndr_dt from @MANTAS@.KDD_CAL k0 where k0.Clndr_Day_Age = 0 and k0.clndr_nm = 'SYSCAL') and ct1.DATA_DUMP_DT > (select k1.clndr_dt from @MANTAS@.KDD_CAL k1 where k1.Clndr_Day_Age = @Look_Back_Period and k1.clndr_nm = 'SYSCAL') -- PR-39791 end -- Parameter that indicates what account are included for customer focus to monitor : -- Y - cover only accounts for which a customer plays a primary role -- N - cover account over which a customer has a discretion and @Primary_Cust_Fl = 'Y' -- Divide By Zero error handling and DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) IS NOT NULL AND DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) <> 0 --OFSAABD-20067 and DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) >= @Min_Indiv_Trans_Amt and DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) <= @Max_Indiv_Trans_Amt ----------------------------------- UNION ALL ----------------------------------- select c.CUST_INTRL_ID , DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) as Trxn_Am , c.CUST_SEQ_ID , ct1.CASH_TRXN_ACTVY_RISK_NB d_ACTVTY_RISK_LVL , ct1.DATA_DUMP_DT , a.ACCT_INTRL_ID , CASE WHEN DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM)-TRUNC(DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM),-@Lrf_Digits)=0 THEN DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) WHEN ct1.TRXN_ACTVY_AM-TRUNC(ct1.TRXN_ACTVY_AM,-@Lrf_Digits)=0 THEN DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) ELSE 0 END as d_LRF_TRXN_AM , c.CUST_EFCTV_RISK_NB , CASE WHEN ct1.CASH_TRXN_NTITY_RISK_NB>0 or ct1.CASH_TRXN_ACTVY_RISK_NB>0 THEN DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) ELSE 0 END d_HR_TRXN_AM , ct1.FUNC_CRNCY_CD from @MINER@.CASH_TRXN ct1 inner join @MINER@.ACCT a on ct1.acct_intrl_id = a.acct_intrl_id inner join @MINER@.CUST_ACCT ca on a.acct_intrl_id = ca.acct_intrl_id inner join @MINER@.CUST c on ca.CUST_INTRL_ID = c.CUST_INTRL_ID inner join @MINER@.CUST_ACCT_ROLE car on ca.cust_acct_role_cd = car.cust_acct_role_cd WHERE -- Exclude cancelled and canceling transactions -- PR 42362 ct1.CXL_PAIR_TRXN_INTRL_ID is null --Exclude Exempted Customers and c.CUST_EFCTV_RISK_NB <> -2 -- Cover customers either from all jurisdiction or from Incl_Jurisdictions_Lst only and (@All_Jurisdictions_Fl='Y' or c.JRSDCN_CD in (@Incl_Jurisdictions_Lst)) -- Include Retail Customer Accounts Only and a.MANTAS_ACCT_HOLDR_TYPE_CD='CR' -- Cover only specific accounts and a.MANTAS_ACCT_BUS_TYPE_CD in (@Mantas_Bus_Acct_Type_Lst) -- and ct1.MANTAS_TRXN_PRDCT_CD in (@Incl_Cash_Trxn_Prdct_Type_Lst) and ct1.MANTAS_TRXN_PURP_CD = 'GENERAL' -- Cover either all transaction or only form the Incl_Trans_Src_Lst and (@All_Trans_Src_Fl='Y' or ct1.SRC_SYS_CD in (@Incl_Trans_Src_Lst)) -- PR-39791 start -- Exclude Cash Transaction Report Exemption Accounts and coalesce (a.CASH_RPT_EXMPT_FL, ' ')<>'Y' and ct1.TRXN_EXCTN_DT <= (select k0.clndr_dt from @MANTAS@.KDD_CAL k0 where k0.Clndr_Day_Age = 0 and k0.clndr_nm = 'SYSCAL') and ct1.TRXN_EXCTN_DT > (select k1.clndr_dt from @MANTAS@.KDD_CAL k1 where k1.Clndr_Day_Age = @Look_Back_Period and k1.clndr_nm = 'SYSCAL') and ct1.DATA_DUMP_DT <= (select k0.clndr_dt from @MANTAS@.KDD_CAL k0 where k0.Clndr_Day_Age = 0 and k0.clndr_nm = 'SYSCAL') and ct1.DATA_DUMP_DT > (select k1.clndr_dt from @MANTAS@.KDD_CAL k1 where k1.Clndr_Day_Age = @Look_Back_Period and k1.clndr_nm = 'SYSCAL') -- PR-39791 end -- Parameter that indicates what account are included for customer focus to monitor : -- Y - cover only accounts for which a customer plays a primary role -- N - cover account over which a customer has a discretion and @Primary_Cust_Fl = 'N' -- Account Customer Role will be viewed as disretionary and (car.trdng_auth_fl = 'Y' or car.wdrwl_auth_fl = 'Y' or car.poa_fl = 'Y') -- Divide By Zero error handling and DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) IS NOT NULL AND DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) <> 0 --OFSAABD-20067 and DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) >= @Min_Indiv_Trans_Amt and DECODE(@Curr_Type,'F',ct1.TRXN_FUNC_AM,ct1.TRXN_BASE_AM) <= @Max_Indiv_Trans_Amt
) t GROUP BY t.CUST_INTRL_ID having -- Frequency Period -- PR-39791 start max(t.data_dump_dt) <= (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL' and b.Clndr_Day_Age = 0 ) and max(t.data_dump_dt) > (select b.CLNDR_DT from @MANTAS@.KDD_CAL b where b.CLNDR_NM = 'SYSCAL' and b.Clndr_Day_Age = @Frequency_Period )) v -- PR-39791 end
where ( ( v.Overall_Risk = 'HR' and v.Trans_Amt >= @HR_Min_Trans_Amt and v.Trans_Ct >=@HR_Min_Trans_Ct ) or ( v.Overall_Risk = 'MR' and v.Trans_Amt >= @MR_Min_Trans_Amt and v.Trans_Ct >=@MR_Min_Trans_Ct ) or ( v.Overall_Risk = 'RR' and v.Trans_Amt >= @RR_Min_Trans_Amt and v.Trans_Ct >=@RR_Min_Trans_Ct ) )
